/*            S T A T I C   F U N C T I O N   I N C L U D E                 */
/*==========================================================================*/

static Boolean vin_c_parse_token (Parse_Context * const parse_context , const char token)
{
  if (parse_context->vin_def_token [0] == token)
    {
      parse_context->vin_def_token++ ;

      return TRUE ;
    }

  return FALSE ;
}

